import pandas as pd
from collections import defaultdict


def run(inputs: dict) -> dict:
    dim = inputs['DIM_ACCOUNT'].copy()
    stg = inputs['STG_ACCOUNT'].copy()

    # Normalize date columns to pandas Timestamps for reliable comparison.
    dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])
    dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    stg['update_date'] = pd.to_datetime(stg['update_date'])

    # Build per-account list of versions (dicts) preserving original data.
    versions = defaultdict(list)
    for _, row in dim.iterrows():
        end_val = row['eff_end_date']
        versions[row['account_id']].append({
            'plan': row['plan'],
            'start': row['eff_start_date'],
            'end': None if pd.isna(end_val) else end_val,
            'is_current': int(row['is_current']) if pd.notna(row['is_current']) else row['is_current'],
        })

    def plans_equal(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na != b_na:
            return False
        return a == b

    # Process staged records in cursor order: account_id, update_date ASC,
    # stable w.r.t. original order for any ties (shouldn't occur given
    # uniqueness of (account_id, update_date) in staging).
    stg_sorted = stg.sort_values(['account_id', 'update_date'], kind='stable')

    for _, s in stg_sorted.iterrows():
        acc = s['account_id']
        plan = s['plan']
        upd = s['update_date']

        vlist = versions[acc]

        if not vlist:
            vlist.append({
                'plan': plan,
                'start': upd,
                'end': None,
                'is_current': 1,
            })
            continue

        # Find the version covering upd: start <= upd < end (end None = open).
        covering = None
        for v in vlist:
            if v['start'] <= upd and (v['end'] is None or upd < v['end']):
                covering = v
                break

        if covering is None:
            # upd is earlier than the account's earliest version's start.
            f = min(vlist, key=lambda v: v['start'])
            vlist.append({
                'plan': plan,
                'start': upd,
                'end': f['start'],
                'is_current': 0,
            })
        else:
            v = covering
            if plans_equal(v['plan'], plan):
                # no-op, unchanged record
                pass
            elif upd == v['start']:
                # same-day correction, no new version
                v['plan'] = plan
            else:
                # split v at upd
                vlist.append({
                    'plan': plan,
                    'start': upd,
                    'end': v['end'],
                    'is_current': v['is_current'],
                })
                v['end'] = upd
                v['is_current'] = 0

    # Build output rows.
    rows = []
    for acc, vlist in versions.items():
        for v in vlist:
            rows.append({
                'account_id': acc,
                'plan': v['plan'],
                'eff_start_date': v['start'],
                'eff_end_date': v['end'],
                'is_current': v['is_current'],
            })

    out = pd.DataFrame(
        rows,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current'],
    )

    if not out.empty:
        out = out.sort_values(['account_id', 'eff_start_date']).reset_index(drop=True)

    return {'dim_account_out': out}
